BEGIN;
CREATE TABLE IF NOT EXISTS employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE,role text NOT NULL CHECK(role IN('owner','manager','cashier','attendant')),password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,employee_id uuid NOT NULL REFERENCES employees(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS shifts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES employees(id),device_id uuid REFERENCES devices(id),opening_cash_cents bigint NOT NULL CHECK(opening_cash_cents>=0),actual_closing_cash_cents bigint CHECK(actual_closing_cash_cents>=0),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,notes text, CHECK(closed_at IS NULL OR closed_at>=opened_at));
CREATE UNIQUE INDEX IF NOT EXISTS one_open_shift_per_employee ON shifts(employee_id) WHERE closed_at IS NULL;
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,category text NOT NULL DEFAULT 'Other',price_cents bigint NOT NULL CHECK(price_cents>=0),stock bigint NOT NULL DEFAULT 0 CHECK(stock>=0),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),delta bigint NOT NULL,reason text NOT NULL,employee_id uuid NOT NULL REFERENCES employees(id),sale_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shift_id uuid NOT NULL REFERENCES shifts(id),employee_id uuid NOT NULL REFERENCES employees(id),total_cents bigint NOT NULL CHECK(total_cents>=0),cash_received_cents bigint NOT NULL CHECK(cash_received_cents>=0),status text NOT NULL DEFAULT 'completed',idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES sales(id),product_id uuid NOT NULL REFERENCES products(id),product_name text NOT NULL,quantity bigint NOT NULL CHECK(quantity>0),unit_price_cents bigint NOT NULL CHECK(unit_price_cents>=0));
CREATE TABLE IF NOT EXISTS equipment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,type text NOT NULL CHECK(type IN('badminton','pickleball','other')),hourly_rate_cents bigint NOT NULL CHECK(hourly_rate_cents>=0),status text NOT NULL DEFAULT 'available' CHECK(status IN('available','rented','maintenance','retired')));
CREATE TABLE IF NOT EXISTS rentals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),equipment_id uuid NOT NULL REFERENCES equipment(id),employee_id uuid NOT NULL REFERENCES employees(id),shift_id uuid NOT NULL REFERENCES shifts(id),hours numeric(8,2) NOT NULL CHECK(hours>0),rate_cents bigint NOT NULL CHECK(rate_cents>=0),total_cents bigint NOT NULL CHECK(total_cents>=0),started_at timestamptz NOT NULL DEFAULT now(),returned_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_rental_per_equipment ON rentals(equipment_id) WHERE returned_at IS NULL;
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY,employee_id uuid REFERENCES employees(id),action text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_outbox(id bigserial PRIMARY KEY,event_type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),synced_at timestamptz);
CREATE INDEX IF NOT EXISTS sync_outbox_pending ON sync_outbox(id) WHERE synced_at IS NULL;
COMMIT;
